    "constraints": [
      "1 <= input.length <= 10^5",
      "Target Time Complexity: O(log N)",
      "Target Space Complexity: O(1)"
    ],
    "approach": "Binary Search Divide & Conquer Halving",
    "intuition": "This problem is optimally solved by traversing the binary search structure while maintaining strict invariants to minimize redundant operations.",
    "stepByStep": [
      "Initialize boundary indices, accumulators, or auxiliary state structures.",
      "Iterate through the data structure while maintaining invariant conditions.",
      "Prune redundant computations and update the candidate answer.",
      "Return the final computed result."
    ],
    "timeComplexity": "O(log N)",
    "spaceComplexity": "O(1)",
    "code": {
      "python": "def searchA2dMatrix(nums: list[int], target: int) -> int:\n    low, high = 0, len(nums) - 1\n    while low <= high:\n        mid = low + (high - low) // 2\n        if nums[mid] == target:\n            return mid\n        elif nums[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1",
      "cpp": "int searchA2dMatrix(vector<int>& nums, int target) {\n    int low = 0, high = (int)nums.size() - 1;\n    while (low <= high) {\n        int mid = low + (high - low) / 2;\n        if (nums[mid] == target) return mid;\n        else if (nums[mid] < target) low = mid + 1;\n        else high = mid - 1;\n    }\n    return -1;\n}",
      "java": "public int searchA2dMatrix(int[] nums, int target) {\n    int low = 0, high = nums.length - 1;\n    while (low <= high) {\n        int mid = low + (high - low) / 2;\n        if (nums[mid] == target) return mid;\n        else if (nums[mid] < target) low = mid + 1;\n        else high = mid - 1;\n    }\n    return -1;\n}",
      "javascript": "function searchA2dMatrix(nums, target) {\n  let low = 0, high = nums.length - 1;\n  while (low <= high) {\n    const mid = Math.floor(low + (high - low) / 2);\n    if (nums[mid] === target) return mid;\n    else if (nums[mid] < target) low = mid + 1;\n    else high = mid - 1;\n  }\n  return -1;\n}"
    },
