    "timeComplexity": "O(N)",
    "spaceComplexity": "O(N)",
    "code": {
      "python": "def insertDeleteGetrandomO1(nums: list[int]) -> bool:\n    seen = set()\n    for x in nums:\n        if x in seen:\n            return True\n        seen.add(x)\n    return False",
      "cpp": "bool insertDeleteGetrandomO1(vector<int>& nums) {\n    unordered_set<int> seen;\n    for (int x : nums) {\n        if (seen.count(x)) return true;\n        seen.insert(x);\n    }\n    return false;\n}",
      "java": "public boolean insertDeleteGetrandomO1(int[] nums) {\n    Set<Integer> seen = new HashSet<>();\n    for (int x : nums) {\n        if (seen.contains(x)) return true;\n        seen.add(x);\n    }\n    return false;\n}",
      "javascript": "function insertDeleteGetrandomO1(nums) {\n  const seen = new Set();\n  for (const x of nums) {\n    if (seen.has(x)) return true;\n    seen.add(x);\n  }\n  return false;\n}"
    },
