    "timeComplexity": "O(N)",
    "spaceComplexity": "O(H)",
    "code": {
      "python": "def sameTree(root):\n    if not root:\n        return []\n    res = []\n    def dfs(node):\n        if not node: return\n        dfs(node.left)\n        res.append(node.val)\n        dfs(node.right)\n    dfs(root)\n    return res",
      "cpp": "vector<int> sameTree(TreeNode* root) {\n    vector<int> res;\n    auto dfs = [&](auto& self, TreeNode* node) -> void {\n        if (!node) return;\n        self(self, node->left);\n        res.push_back(node->val);\n        self(self, node->right);\n    };\n    dfs(dfs, root);\n    return res;\n}",
      "java": "public List<Integer> sameTree(TreeNode root) {\n    List<Integer> res = new ArrayList<>();\n    dfs(root, res);\n    return res;\n}\nprivate void dfs(TreeNode node, List<Integer> res) {\n    if (node == null) return;\n    dfs(node.left, res);\n    res.add(node.val);\n    dfs(node.right, res);\n}",
      "javascript": "function sameTree(root) {\n  const res = [];\n  function dfs(node) {\n    if (!node) return;\n    dfs(node.left);\n    res.push(node.val);\n    dfs(node.right);\n  }\n  dfs(root);\n  return res;\n}"
    },
