      "cpp": "#include <vector>\n#include <queue>\nusing namespace std;\n\nbool connectedComponents(int numCourses, vector<vector<int>>& prerequisites) {\n    vector<vector<int>> adj(numCourses);\n    vector<int> indegree(numCourses, 0);\n    for (auto& p : prerequisites) {\n        adj[p[1]].push_back(p[0]);\n        indegree[p[0]]++;\n    }\n    queue<int> q;\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) q.push(i);\n    }\n    int visited = 0;\n    while (!q.empty()) {\n        int node = q.front(); q.pop();\n        visited++;\n        for (int neighbor : adj[node]) {\n            if (--indegree[neighbor] == 0) q.push(neighbor);\n        }\n    }\n    return visited == numCourses;\n}",
      "java": "public boolean connectedComponents(int numCourses, int[][] prerequisites) {\n    List<List<Integer>> adj = new ArrayList<>();\n    for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());\n    int[] indegree = new int[numCourses];\n    for (int[] p : prerequisites) {\n        adj.get(p[1]).add(p[0]);\n        indegree[p[0]]++;\n    }\n    Queue<Integer> q = new LinkedList<>();\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) q.add(i);\n    }\n    int visited = 0;\n    while (!q.isEmpty()) {\n        int node = q.poll();\n        visited++;\n        for (int neighbor : adj.get(node)) {\n            if (--indegree[neighbor] == 0) q.add(neighbor);\n        }\n    }\n    return visited == numCourses;\n}",
      "javascript": "function connectedComponents(numCourses, prerequisites) {\n  const adj = Array.from({ length: numCourses }, () => []);\n  const indegree = new Array(numCourses).fill(0);\n  for (const [dest, src] of prerequisites) {\n    adj[src].push(dest);\n    indegree[dest]++;\n  }\n  const q = [];\n  for (let i = 0; i < numCourses; i++) {\n    if (indegree[i] === 0) q.push(i);\n  }\n  let visited = 0;\n  while (q.length > 0) {\n    const node = q.shift();\n    visited++;\n    for (const neighbor of adj[node]) {\n      indegree[neighbor]--;\n      if (indegree[neighbor] === 0) q.push(neighbor);\n    }\n  }\n  return visited === numCourses;\n}"
