    "spaceComplexity": "O(N)",
    "code": {
      "python": "def fibonacci(n: int) -> int:\n    if n <= 1: return n\n    dp = [0] * (n + 1)\n    dp[0], dp[1] = 0, 1\n    for i in range(2, n + 1):\n        dp[i] = dp[i - 1] + dp[i - 2]\n    return dp[n]",
      "cpp": "int fibonacci(int n) {\n    if (n <= 1) return n;\n    vector<int> dp(n + 1, 0);\n    dp[0] = 0; dp[1] = 1;\n    for (int i = 2; i <= n; i++) {\n        dp[i] = dp[i - 1] + dp[i - 2];\n    }\n    return dp[n];\n}",
      "java": "public int fibonacci(int n) {\n    if (n <= 1) return n;\n    int[] dp = new int[n + 1];\n    dp[0] = 0; dp[1] = 1;\n    for (int i = 2; i <= n; i++) {\n        dp[i] = dp[i - 1] + dp[i - 2];\n    }\n    return dp[n];\n}",
      "javascript": "function fibonacci(n) {\n  if (n <= 1) return n;\n  const dp = new Array(n + 1).fill(0);\n  dp[0] = 0; dp[1] = 1;\n  for (let i = 2; i <= n; i++) {\n    dp[i] = dp[i - 1] + dp[i - 2];\n  }\n  return dp[n];\n}"
    },
